const capabilityTypes = new Set(['resource.skill', 'resource.tool', 'resource.mcp', 'resource.plugin']);

export default {
  description: 'Return bounded direct Workflow V3 context for one Command or Agent node.',
  input: {"type":"object","properties":{"workflowJson":{"type":"string","maxLength":950000,"description":"完整 Workflow V3 JSON"},"currentNodeID":{"type":"string","minLength":1,"maxLength":100,"description":"Target Command 或 Agent node ID"}},"required":["workflowJson","currentNodeID"],"additionalProperties":false},
  async execute(args, context) {

    let workflow;
    try {
      workflow = JSON.parse(args.workflowJson);
    } catch {
      return failure('workflowJson 不是有效 JSON。');
    }
    if (!workflow || typeof workflow !== 'object' || workflow.schemaVersion !== 'agent-system.workflow.v3' || !Array.isArray(workflow.nodes) || !Array.isArray(workflow.edges)) {
      return failure('輸入不是完整 Workflow V3 object。');
    }

    const nodes = workflow.nodes;
    const edges = workflow.edges;
    const byID = new Map(nodes.map((node) => [node?.id, node]));
    const targetNode = byID.get(args.currentNodeID);
    if (!targetNode) return failure('找不到 target node。');
    if (targetNode.type !== 'resource.command' && targetNode.type !== 'resource.agent') {
      return failure('Target node 必須是 resource.command 或 resource.agent。');
    }

    const commandNodes = nodes.filter((node) => node?.type === 'resource.command');
    const entryEdges = edges.filter((edge) => edge?.kind === 'capability' && edge?.sourceHandle === 'capability' && edge?.targetHandle === 'agent' && byID.get(edge?.source)?.type === 'resource.command' && byID.get(edge?.target)?.type === 'resource.agent');
    const delegations = edges.filter((edge) => edge?.kind === 'delegation' && edge?.sourceHandle === 'delegation' && edge?.targetHandle === 'agent' && byID.get(edge?.source)?.type === 'resource.agent' && byID.get(edge?.target)?.type === 'resource.agent');
    const primaryIDs = new Set(entryEdges.map((edge) => edge.target));
    const subagentIDs = new Set();
    const queue = [...primaryIDs];
    while (queue.length > 0) {
      const parent = queue.shift();
      for (const edge of delegations) {
        if (edge.source !== parent || subagentIDs.has(edge.target)) continue;
        subagentIDs.add(edge.target);
        queue.push(edge.target);
      }
    }

    const currentAgentIDs = targetNode.type === 'resource.agent'
      ? [targetNode.id]
      : entryEdges.filter((edge) => edge.source === targetNode.id).map((edge) => edge.target);
    if (currentAgentIDs.length !== 1) return failure('Target must resolve to exactly one current Agent.');
    const currentAgentID = currentAgentIDs[0];
    const role = primaryIDs.has(currentAgentID) && subagentIDs.has(currentAgentID)
      ? 'conflict'
      : primaryIDs.has(currentAgentID)
        ? 'primary'
        : subagentIDs.has(currentAgentID)
          ? 'subagent'
          : 'unresolved';
    if (role === 'conflict') return failure('Current Agent resolves as both primary and subagent.');

    const directCapabilities = edges
      .filter((edge) => edge?.kind === 'capability' && edge?.sourceHandle === 'capability' && edge?.targetHandle === 'capability' && edge?.target === currentAgentID && capabilityTypes.has(byID.get(edge?.source)?.type))
      .map((edge) => summarizeResource(byID.get(edge.source), edge.id));
    const directParents = delegations.filter((edge) => edge.target === currentAgentID).map((edge) => summarizeAgent(byID.get(edge.source), edge.id));
    const directDelegatedChildren = delegations.filter((edge) => edge.source === currentAgentID).map((edge) => summarizeAgent(byID.get(edge.target), edge.id));
    const commandEntry = entryEdges.find((edge) => edge.target === currentAgentID);

    return { content: JSON.stringify({
        valid: true,
        targetNode,
        commandCount: commandNodes.length,
        currentAgent: summarizeAgent(byID.get(currentAgentID)),
        currentAgentRole: role,
        commandEntry: commandEntry ? { edgeID: commandEntry.id, commandNodeID: commandEntry.source, agentNodeID: commandEntry.target } : null,
        directCapabilities,
        directParents,
        directDelegatedChildren,
      }), metadata: { title: 'Workflow V3 direct context ready' } };
  },
};

function summarizeResource(node, edgeID) {
  return { edgeID, nodeID: node?.id, type: node?.type, name: node?.data?.name, scope: node?.data?.scope, mode: node?.data?.mode };
}

function summarizeAgent(node, edgeID) {
  return { ...(edgeID ? { edgeID } : {}), nodeID: node?.id, name: node?.data?.name, scope: node?.data?.scope, mode: node?.data?.mode };
}

function failure(message) {
  return { content: JSON.stringify({ valid: false, error: message }), metadata: { title: 'Workflow V3 context unavailable' } };
}

const workflowReference = "__BACKEND_SESSION_WORKFLOW__";
async function resolveWorkflowJson(workflowJson, context) {
  if (workflowJson && typeof workflowJson === "object" && !Array.isArray(workflowJson)) return workflowJson;
  if (typeof workflowJson !== "string") throw new Error("workflowJson must be a Workflow V3 JSON string or object.");
  const reference = workflowJson.startsWith(workflowReference + ":") ? workflowJson.slice(workflowReference.length + 1) : undefined;
  if (workflowJson !== workflowReference && reference === undefined) return JSON.parse(workflowJson);
  const baseURL = (process.env.AGENT_SYSTEM_BFF_BASE_URL || "http://agent-system-backend:8000").replace(/\/+$/, "");
  const directory = typeof context?.directory === "string" ? context.directory.replace(/\\/g, "/") : "";
  const project = reference ? decodeURIComponent(reference) : directory.match(/\/workflow\/projects\/([^/]+)\/?$/)?.[1];
  if (!project || typeof context?.sessionID !== "string") throw new Error("Backend Workflow context is unavailable.");
  const endpoint = new URL("/bff/workflow-resources/test-chat/" + encodeURIComponent(context.sessionID) + "/context", baseURL);
  endpoint.searchParams.set("project", project);
  const response = await fetch(endpoint, { headers: { "x-agent-system-workspace": project }, signal: AbortSignal.timeout(15_000) });
  const payload = await response.json().catch(() => undefined);
  if (!response.ok || !payload?.input?.workflow) throw new Error("Backend Workflow context is unavailable.");
  return payload.input.workflow;
}
function frontmatterOf(content) {
  if (typeof content !== "string") return undefined;
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
  return match ? match[0] : undefined;
}

const placeholderWord = /(?:^|\n)\s*(?:TODO|TBD|PLACEHOLDER)\s*(?:$|[:：-])/im;
const placeholder = /<(?:request|value|API_KEY|ACCESS_TOKEN|SECRET|TOKEN|YOUR_[A-Z0-9_]{1,64}|(?:insert|INSERT)(?:[-_ ][A-Za-z0-9_. -]{0,64})?|\.\.\.)>|\{\{/;

export default {
  description: "Deterministically validate one Command or Agent Markdown success contract against Workflow V3 graph identity.",
  input: {
    type: "object",
