  async execute(args, context) {
    let workflow;
    try {
      workflow = await resolveWorkflowJson(args.workflowJson, context);
    } catch (error) {
      const message = error instanceof Error ? error.message : "workflowJson could not be resolved.";
      return failure("PROMPT_WRITER_CONTEXT_INVALID", message);
    }
    if (!isRecord(workflow) || workflow.schemaVersion !== "agent-system.workflow.v3" || !Array.isArray(workflow.nodes) || !Array.isArray(workflow.edges)) {
      return failure("PROMPT_WRITER_CONTEXT_INVALID", "workflowJson is not a complete Workflow V3 object.");
    }
    const target = workflow.nodes.find((node) => isRecord(node) && node.id === args.targetNodeID);
