      || (target.type !== "resource.command" && target.type !== "resource.agent")) {
      return failure("PROMPT_WRITER_TARGET_INVALID", "targetNodeID must identify a Command or Agent node.");
    }
    const fence = String.fromCharCode(96).repeat(3);
    const rawContent = typeof args.content === "string" ? args.content.trim() : "";
    const markdownFence = new RegExp("^" + fence + "markdown\\r?\\n([\\s\\S]+)\\r?\\n" + fence + "$");
    const genericFence = new RegExp("^" + fence + "\\r?\\n([\\s\\S]+)\\r?\\n" + fence + "$");
    const genericMatch = genericFence.exec(rawContent);
    let normalizedContent = rawContent;
    if (!markdownFence.test(rawContent)) normalizedContent = genericMatch
      ? fence + "markdown\n" + genericMatch[1] + "\n" + fence
      : fence + "markdown\n" + rawContent + "\n" + fence;
    const match = normalizedContent.match(markdownFence);
    if (!match || match[1].includes(fence)) {
      return failure("PROMPT_WRITER_OUTPUT_INVALID", "Success output must be exactly one markdown code fence.");
    }
    const targetFrontmatter = frontmatterOf(target.data.content);
    const candidateFrontmatter = frontmatterOf(match[1]);
    if (!targetFrontmatter || !candidateFrontmatter) {
      return failure("PROMPT_WRITER_SCOPE_INVALID", "Prompt Writer output must preserve the target frontmatter and update only prompt/body content.");
    }
    if (candidateFrontmatter !== targetFrontmatter) {
      return failure("PROMPT_WRITER_SCOPE_INVALID", "Prompt Writer must preserve target frontmatter byte-for-byte and update only prompt/body content.");
    }
    const guardedContent = targetFrontmatter + match[1].slice(candidateFrontmatter.length);
    normalizedContent = fence + "markdown\n" + guardedContent + "\n" + fence;
    const body = match[1];
    const frontmatter = parseFrontmatter(body);
    if (!frontmatter || !frontmatter.body.trim()) {
      return failure("PROMPT_WRITER_FRONTMATTER_INVALID", "Markdown must contain frontmatter and non-empty instructions.");
    }
    const scalarKeys = target.type === "resource.command"
      ? ["description", "agent", "model", "variant"]
      : ["name", "description", "mode", "model", "variant", "disabled", "disable"];
    if (hasUnsupportedYamlSyntax(frontmatter.lines) || hasAmbiguousScalarFields(frontmatter.lines, scalarKeys)) {
      return failure("PROMPT_WRITER_FRONTMATTER_INVALID", "Markdown frontmatter must use one unambiguous scalar value per field and simple map syntax.");
    }
    if (placeholderWord.test(body) || placeholder.test(body)) {
      return failure("PROMPT_WRITER_PLACEHOLDER", "Markdown must not contain unresolved placeholders.");
    }
    if (containsSecretLiteral(body)) {
      return failure("PROMPT_WRITER_SECRET_DETECTED", "Markdown must not contain plaintext credentials.");
    }

    if (target.type === "resource.command") {
      const entries = workflow.edges.filter((edge) => isRecord(edge)
        && edge.kind === "capability" && edge.source === target.id && edge.targetHandle === "agent");
      const entryAgent = entries.length === 1
        ? workflow.nodes.find((node) => isRecord(node) && node.id === entries[0].target)
        : undefined;
      if (!isRecord(entryAgent) || !isRecord(entryAgent.data)
        || scalar(frontmatter.lines, "agent") !== entryAgent.data.name
        || !scalar(frontmatter.lines, "description")) {
        return failure("PROMPT_WRITER_COMMAND_AGENT_INVALID", "Command frontmatter must name its unique entry Agent and include description.");
      }
      if (!frontmatter.body.includes("$ARGUMENTS")) {
        return failure("PROMPT_WRITER_ARGUMENTS_MISSING", "Command content must preserve $ARGUMENTS.");
      }
      if (!preservesRuntimeFields(target, frontmatter.lines, args.request)) {
        return failure("PROMPT_WRITER_RUNTIME_FIELD_INVALID", "Command model and variant may change only when the request names the exact new value.");
      }
      return { content: normalizedContent, metadata: { title: "Validated prompt output" } };
    }

    const nativeV2 = hasRootField(frontmatter.lines, "permissions");
    if ((!nativeV2 && scalar(frontmatter.lines, "name") !== target.data.name)
      || !scalar(frontmatter.lines, "description")) {
      return failure("PROMPT_WRITER_AGENT_IDENTITY_INVALID", "Agent frontmatter must preserve its V1 identity when applicable and include description.");
    }
    const unsupportedFields = nativeV2 ? unsupportedNativeV2AgentFields(frontmatter.lines) : [];
    if (nativeV2 && unsupportedFields.length > 0) {
      return failure("PROMPT_WRITER_FRONTMATTER_INVALID", `Native V2 Agent frontmatter contains unsupported V1 field(s): ${unsupportedFields.join(", ")}.`);
    }
    if (nativeV2 && !parseNativePermissionRules(frontmatter.lines).valid) {
      return failure("PROMPT_WRITER_FRONTMATTER_INVALID", "Native V2 Agent frontmatter must use an ordered permissions list.");
    }
    const entryEdges = workflow.edges.filter((edge) => isRecord(edge)
      && edge.kind === "capability" && edge.target === target.id && edge.targetHandle === "agent"
      && workflow.nodes.some((node) => isRecord(node) && node.id === edge.source && node.type === "resource.command"));
    const parentEdges = workflow.edges.filter((edge) => isRecord(edge) && edge.kind === "delegation" && edge.target === target.id);
    const expectedMode = entryEdges.length === 1 && parentEdges.length === 0
      ? "primary"
      : entryEdges.length === 0 && parentEdges.length > 0
        ? "subagent"
        : undefined;
    if (!expectedMode || scalar(frontmatter.lines, "mode") !== expectedMode) {
      return failure("PROMPT_WRITER_AGENT_MODE_INVALID", "Agent mode must match its graph role.");
    }
    const childNames = workflow.edges
      .filter((edge) => isRecord(edge) && edge.kind === "delegation" && edge.source === target.id)
      .map((edge) => workflow.nodes.find((node) => isRecord(node) && node.id === edge.target)?.data)
      .filter(isRecord)
      .map((data) => data.name)
      .filter((name) => typeof name === "string");
    const permissionIssue = nativeV2
      ? validateNativeAgentPermissions(frontmatter, parseNativePermissionRules(frontmatter.lines).rules, workflow, target, childNames)
      : validateTaskPolicy(frontmatter.lines, childNames) || validateAgentPermissions(frontmatter, workflow, target, childNames);
    if (permissionIssue) return failure("PROMPT_WRITER_PERMISSION_INVALID", permissionIssue);
    if (!preservesRuntimeFields(target, frontmatter.lines, args.request)) {
      return failure("PROMPT_WRITER_RUNTIME_FIELD_INVALID", "Agent model and variant may change only when the request names the exact new value.");
    }
    return { content: normalizedContent, metadata: { title: "Validated prompt output" } };
  },
};

function hasRootField(lines, key) {
  const pattern = new RegExp(`^(?:${escapeRegExp(key)}|"${escapeRegExp(key)}"|'${escapeRegExp(key)}')\\s*:`);
  return lines.some((line) => leadingSpaces(line) === 0 && pattern.test(line.trim()));
}
function unsupportedNativeV2AgentFields(lines) {
  const unsupported = new Set(["name", "permission", "tools", "skills", "temperature", "top_p", "variant", "prompt", "disable"]);
  return lines.flatMap((line) => {
    if (leadingSpaces(line) !== 0) return [];
    const match = line.trim().match(/^(?:"([^\"]+)"|'([^']+)'|([A-Za-z][A-Za-z0-9_-]*))\s*:/);
