  for (const child of expected) {
    if (!taskChildren.some((entry) => entry.key === child && entry.value === "allow")) return "Agent task allowlist omits a direct child.";
  }
  return undefined;
}

function validateAgentPermissions(frontmatter, workflow, target, childNames) {
  const tools = mapEntries(frontmatter.lines, "tools");
  const permissions = mapEntries(frontmatter.lines, "permission");
  const toolWildcards = tools.filter((entry) => entry.key === "*");
